import type { SkillFile, SkillSource } from '../src/skills/source.js'
import { readdir, readFile, rename, writeFile } from 'node:fs/promises'
import { join, relative, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseFrontmatter } from '../src/skills/frontmatter.js'
import { SKILL_FILE } from '../src/skills/source.js'

const MARKDOWN_SUFFIX = '.md'
const GENERATED_FILE = 'collection.generated.ts'
const SKILL_NAME_RE = /^[a-z0-9-]+$/

const HEADER = [
  '// @generated by scripts/generate-skill-collection.ts — DO NOT EDIT.',
  '// Regenerate via `pnpm skills:gen`. Drift gated by `pnpm skills:check` in CI.',
]

async function walk(dir: string): Promise<string[]> {
  const out: string[] = []
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name)
    if (entry.isDirectory()) out.push(...(await walk(full)))
    else if (entry.isFile()) out.push(full)
  }
  return out
}

function toPosix(p: string): string {
  return p.split(sep).join('/')
}

function compareStrings(a: string, b: string): number {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}

function assertFrontmatter(name: string, text: string): void {
  const meta = parseFrontmatter(text)
  if (meta.name !== name)
    throw new Error(`${name}/${SKILL_FILE}: frontmatter name must be "${name}"`)
  if (typeof meta.description !== 'string' || meta.description.trim() === '')
    throw new Error(`${name}/${SKILL_FILE}: frontmatter description is required`)
}

async function readSkill(skillsDir: string, name: string): Promise<SkillSource> {
  if (!SKILL_NAME_RE.test(name)) throw new Error(`${name}: skill folder names are [a-z0-9-]`)
  const dir = join(skillsDir, name)
  const paths = (await walk(dir))
    .filter((abs) => abs.endsWith(MARKDOWN_SUFFIX))
    .map((abs) => toPosix(relative(dir, abs)))
    .sort(compareStrings)
  if (!paths.includes(SKILL_FILE)) throw new Error(`${name}: missing ${SKILL_FILE}`)
  const files: SkillFile[] = []
  for (const path of paths) files.push({ path, text: await readFile(join(dir, path), 'utf8') })
  const skillFile = files.find((file) => file.path === SKILL_FILE) as SkillFile
  assertFrontmatter(name, skillFile.text)
  return { name, files }
}

export async function discoverSkills(skillsDir: string): Promise<SkillSource[]> {
  const names = (await readdir(skillsDir, { withFileTypes: true }))
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort(compareStrings)
  const skills: SkillSource[] = []
  for (const name of names) skills.push(await readSkill(skillsDir, name))
  if (skills.length === 0) throw new Error(`no skills found under ${skillsDir}`)
  return skills
}

function escapeTemplate(text: string): string {
  return text.replaceAll('\\', '\\\\').replaceAll('`', '\\`').replaceAll('${', '\\${')
}

export function formatModule(skills: readonly SkillSource[]): string {
  const lines = [
    ...HEADER,
    '',
    `import type { SkillSource } from '@/skills/source'`,
    '',
    'export const SKILL_SOURCES: readonly SkillSource[] = [',
  ]
  for (const skill of skills) {
    lines.push('  {', `    name: '${skill.name}',`, '    files: [')
    for (const file of skill.files) {
      lines.push(
        '      {',
        `        path: '${file.path}',`,
        `        text: \`${escapeTemplate(file.text)}\`,`,
        '      },',
      )
    }
    lines.push('    ],', '  },')
  }
  lines.push(']', '')
  return lines.join('\n')
}

export type GenerateOptions = {
  readonly skillsDir: string
  readonly target: string
  readonly mode: 'write' | 'check'
}

export type GenerateResult =
  | { mode: 'write'; wrote: boolean; path: string }
  | { mode: 'check'; ok: true; path: string }
  | { mode: 'check'; ok: false; path: string; diff: string }

export async function generate(opts: GenerateOptions): Promise<GenerateResult> {
  const content = formatModule(await discoverSkills(opts.skillsDir))

  if (opts.mode === 'check') {
    let onDisk = ''
    try {
      onDisk = await readFile(opts.target, 'utf8')
    } catch {
      onDisk = ''
    }
    if (onDisk === content) return { mode: 'check', ok: true, path: opts.target }
    return { mode: 'check', ok: false, path: opts.target, diff: shortDiff(onDisk, content) }
  }

  const tmp = `${opts.target}.tmp-${process.pid}-${Date.now()}`
  await writeFile(tmp, content, 'utf8')
  await rename(tmp, opts.target)
  return { mode: 'write', wrote: true, path: opts.target }
}

function shortDiff(a: string, b: string): string {
  const aLines = a.split('\n')
  const bLines = b.split('\n')
  const lines: string[] = []
  const max = Math.max(aLines.length, bLines.length)
  for (let i = 0; i < max; i++) {
    if (aLines[i] !== bLines[i]) {
      if (aLines[i] !== undefined) lines.push(`- ${aLines[i]}`)
      if (bLines[i] !== undefined) lines.push(`+ ${bLines[i]}`)
    }
  }
  return lines.slice(0, 40).join('\n')
}

async function main(): Promise<void> {
  const here = fileURLToPath(import.meta.url)
  const skillsDir = join(here, '..', '..', '..', 'skills')
  const target = join(here, '..', '..', 'src', 'skills', GENERATED_FILE)
  const checkMode = process.argv.includes('--check')
  const result = await generate({ skillsDir, target, mode: checkMode ? 'check' : 'write' })

  if (result.mode === 'write') {
    process.stderr.write(`skills:gen wrote ${result.path}\n`)
    return
  }
  if (result.ok) {
    process.stderr.write(`skills:check ok\n`)
    return
  }
  process.stderr.write(
    `skills:check FAILED — ${GENERATED_FILE} is stale.\nDiff (first 40 lines):\n${result.diff}\n\nRun \`pnpm skills:gen\` and commit.\n`,
  )
  process.exit(1)
}

const invokedDirectly =
  process.argv[1] !== undefined && fileURLToPath(import.meta.url) === process.argv[1]

if (invokedDirectly) await main()
